1. Create frontend/src/pages/EmergencyCard.jsx — a public page (no auth required) that reads :token from URL params, calls GET /api/emergency/{token}/, and displays the emergency card:
```jsx
import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { API_BASE_URL } from '../services/api';

function EmergencyCard() {
  const { token } = useParams();
  const [card, setCard] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${API_BASE_URL}/emergency/${token}/`)
      .then(r => r.ok ? r.json() : Promise.reject(r.status))
      .then(data => { setCard(data); setLoading(false); })
      .catch(() => { setError('This emergency card is invalid or has been revoked.'); setLoading(false); });
  }, [token]);

  if (loading) return <div style={{ color: '#fff', textAlign: 'center', padding: '4rem', fontFamily: 'monospace' }}>Loading emergency card...</div>;
  if (error) return <div style={{ color: '#ff3366', textAlign: 'center', padding: '4rem', fontFamily: 'monospace' }}>{error}</div>;

  return (
    <div style={{ minHeight: '100vh', background: '#000326', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '2rem', fontFamily: 'monospace' }}>
      <div style={{ maxWidth: '480px', width: '100%', background: 'rgba(0,4,45,0.92)', border: '2px solid #ff3366', borderRadius: '12px', padding: '2rem', color: '#fff' }}>
        <div style={{ textAlign: 'center', marginBottom: '1.5rem' }}>
          <div style={{ color: '#ff3366', fontSize: '0.7rem', letterSpacing: '0.1em', marginBottom: '0.5rem' }}>🚨 EMERGENCY MEDICAL CARD</div>
          <h2 style={{ fontSize: '1.6rem', fontWeight: 800, margin: 0 }}>{card.name}</h2>
          <div style={{ color: 'rgba(255,255,255,0.5)', fontSize: '0.75rem', marginTop: '0.25rem' }}>ID: {card.vault_id}</div>
        </div>
        <div style={{ display: 'grid', gap: '0.75rem' }}>
          <Field label='BLOOD GROUP' value={card.blood_group || 'Not recorded'} highlight />
          <Field label='ALLERGIES' value={card.allergies?.length > 0 ? card.allergies.join(', ') : 'None recorded'} danger />
          <Field label='EMERGENCY CONTACT' value={card.emergency_contact || 'Not recorded'} />
          <Field label='ACTIVE MEDICATIONS' value={card.active_meds?.length > 0 ? card.active_meds.join(', ') : 'None recorded'} />
          <Field label='LAST UPDATED' value={card.last_updated} />
        </div>
        <div style={{ marginTop: '1.5rem', fontSize: '0.65rem', color: 'rgba(255,255,255,0.35)', textAlign: 'center', lineHeight: '1.5' }}>
          This card is generated by MedFusion AI for emergency use only. Always contact a licensed physician for medical decisions.
        </div>
      </div>
    </div>
  );
}

function Field({ label, value, highlight, danger }) {
  return (
    <div style={{ background: 'rgba(255,255,255,0.04)', borderRadius: '8px', padding: '0.75rem 1rem', border: `1px solid ${danger ? 'rgba(255,51,102,0.3)' : 'rgba(255,255,255,0.08)'}` }}>
      <div style={{ fontSize: '0.58rem', letterSpacing: '0.08em', color: danger ? '#ff3366' : 'rgba(255,255,255,0.45)', marginBottom: '0.25rem' }}>{label}</div>
      <div style={{ fontSize: highlight ? '1.2rem' : '0.9rem', fontWeight: highlight ? 800 : 600, color: highlight ? '#ff8f00' : '#fff' }}>{value}</div>
    </div>
  );
}

export default EmergencyCard;
```

3. In frontend/src/pages/Profile.jsx: add emergency QR state and handlers. At the top of Profile function, add:
```js
const [emergencyToken, setEmergencyToken] = useState(null);
const [emergencyLoading, setEmergencyLoading] = useState(false);

const handleGenerateToken = async () => {
  setEmergencyLoading(true);
  try {
    const res = await api.post('/emergency/generate/');
    setEmergencyToken(res.data.token);
  } catch(err) {
    console.error('Failed to generate emergency token', err);
  } finally {
    setEmergencyLoading(false);
  }
};

const handleRevokeToken = async () => {
  setEmergencyLoading(true);
  try {
    await api.delete('/emergency/revoke/');
    setEmergencyToken(null);
  } catch(err) {
    console.error('Failed to revoke emergency token', err);
  } finally {
    setEmergencyLoading(false);
  }
};
```
 Then pass `emergencyToken`, `emergencyLoading`, `handleGenerateToken`, `handleRevokeToken` as props to `<ProfileIdentity />`.

